namespace {
inline int64_t FloorDiv(int64_t a, int64_t b) {
    return static_cast<int64_t>(std::floor(static_cast<double>(a) / static_cast<double>(b)));
}
}

namespace optiling {
const uint32_t BLOCK_DIM = 8;
const uint32_t TILE_NUM = 8;

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // 输入 x: [N, C_in, H, W]，权重 w: [C_out, C_in, kH, kW]
    auto xShapePtr = context->GetInputShape(0);
    auto wShapePtr = context->GetInputShape(1);

    if (xShapePtr == nullptr || wShapePtr == nullptr) {
        return ge::GRAPH_FAILED;
    }

    const auto &xShape = xShapePtr->GetOriginShape();
    const auto &wShape = wShapePtr->GetOriginShape();

    if (xShape.GetDimNum() != 4 || wShape.GetDimNum() != 4) {
        return ge::GRAPH_FAILED;
    }

    uint32_t N  = static_cast<uint32_t>(xShape.GetDim(0));
    uint32_t C  = static_cast<uint32_t>(xShape.GetDim(1));
    uint32_t H  = static_cast<uint32_t>(xShape.GetDim(2));
    uint32_t Wi = static_cast<uint32_t>(xShape.GetDim(3));

    uint32_t Co = static_cast<uint32_t>(wShape.GetDim(0));
    uint32_t Ci = static_cast<uint32_t>(wShape.GetDim(1));
    uint32_t kH = static_cast<uint32_t>(wShape.GetDim(2));
    uint32_t kW = static_cast<uint32_t>(wShape.GetDim(3));

    // 仅支持 stride=1, padding=0, dilation=1, groups=1 的常见场景
    uint32_t strideH = 1, strideW = 1;
    uint32_t padH = 0, padW = 0;
    uint32_t dilH = 1, dilW = 1;

    if (Ci != C) { // groups=1 场景
        return ge::GRAPH_FAILED;
    }

    // 输出尺寸
    int64_t oh = FloorDiv((int64_t)H + 2 * (int64_t)padH - (int64_t)dilH * ((int64_t)kH - 1) - 1, (int64_t)strideH) + 1;
    int64_t ow = FloorDiv((int64_t)Wi + 2 * (int64_t)padW - (int64_t)dilW * ((int64_t)kW - 1) - 1, (int64_t)strideW) + 1;
    if (oh <= 0 || ow <= 0) {
        return ge::GRAPH_FAILED;
    }

    ConvStandard2dAsymmetricInputAsymmetricKernelCustomTilingData tiling;
    tiling.set_n(N);
    tiling.set_cIn(C);
    tiling.set_cOut(Co);
    tiling.set_h(H);
    tiling.set_w(Wi);
    tiling.set_kH(kH);
    tiling.set_kW(kW);
    tiling.set_strideH(strideH);
    tiling.set_strideW(strideW);
    tiling.set_padH(padH);
    tiling.set_padW(padW);
    tiling.set_dilH(dilH);
    tiling.set_dilW(dilW);
    tiling.set_outH(static_cast<uint32_t>(oh));
    tiling.set_outW(static_cast<uint32_t>(ow));
    tiling.set_tileNum(TILE_NUM);

    context->SetBlockDim(BLOCK_DIM);
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

