at::Tensor conv_standard_2d_asymmetric_input_asymmetric_kernel_custom_impl_npu(
    const at::Tensor& x, const at::Tensor& w) {
    // 输出形状推断：仅支持 stride=1, pad=0, dil=1
    TORCH_CHECK(x.dim() == 4 && w.dim() == 4, \"x/w must be 4D\");
    TORCH_CHECK(x.size(1) == w.size(1), \"in_channels mismatch\");
    const auto N = x.size(0);
    const auto C = x.size(1);
    const auto H = x.size(2);
    const auto W = x.size(3);
    const auto Co = w.size(0);
    const auto kH = w.size(2);
    const auto kW = w.size(3);

    auto Oh = (H - kH) + 1;
    auto Ow = (W - kW) + 1;
    TORCH_CHECK(Oh > 0 && Ow > 0, \"Invalid output shape\");

    at::Tensor y = at::empty({N, Co, Oh, Ow}, x.options());
    EXEC_NPU_CMD(aclnnConvStandard2dAsymmetricInputAsymmetricKernelCustom, x, w, y);
    return y;
